export function mountMultiverse(){
 const section=document.createElement('section');section.className='multiverse wrap';section.id='multiverse';
 section.innerHTML=`<div class="multiverse-intro"><figure><img src="/assets/loki-multiverse.jpg" width="1920" height="1080" alt="Loki сериалындағы жасыл түспен жарқыраған, уақыт тармақтарынан құралған мультиәлем ағашы" loading="lazy"><figcaption>Loki, 2-маусым (2023) · © Marvel Studios.<br>Кадр дереккөзі: <a href="https://www.20minutos.es/cinemania/series/final-loki-temporada-2-explicado-peor-momento-marvel-5189130/" target="_blank" rel="noopener">20minutos ↗</a></figcaption></figure><div><span class="eyebrow">БІР БАСТАУ · ТҮРЛІ БОЛАШАҚ</span><h2>Мультиәлем:<br><em>әр таңдау — жаңа тармақ.</em></h2><p>Loki-дегі уақыт ағашын елестет: бір діңнен көптеген уақыт желісі тарайды. Тармақталуды түсіну үшін өзіміздің шағын, ойдан құрастырылған оқиғамызды жасайық.</p><p>Бүгін сен жұмбақ портал таптың. Оған кіресің бе? Кездескен бейтаныс адамға сенесің бе? Екі таңдау — төрт ықтимал оқиға желісі.</p><a class="multiverse-source" href="https://www.framestore.com/work/loki-season-2" target="_blank" rel="noopener">Уақыт ағашының визуалдық идеясы: Framestore ↗</a></div></div><div class="multiverse-play"><div class="multiverse-bar"><span>ОҚИҒАЛАР АҒАШЫ</span><span id="universe-count">0 / 2 ТАҢДАУ</span></div><div id="universe-tree"></div><div class="universe-controls"><div><span class="eyebrow">ӨЗ ОҚИҒАҢДЫ ТАҢДА</span><h3 id="universe-question"></h3><p id="universe-result" aria-live="polite"></p></div><div class="universe-buttons"><button id="universe-yes" class="btn small"></button><button id="universe-no" class="btn secondary small"></button><button id="universe-reset" class="btn secondary small">Басынан ↻</button></div></div></div><div class="multiverse-meaning"><p><b>Тамыр</b> — ортақ бастау.<br><b>Тармақ</b> — таңдалған бағыт.<br><b>Жапырақ</b> — оқиғаның нәтижесі.</p><p>Бұл оқиғалар ағашы алдын ала ойдан құрастырылған: ол физикалық теория да, ықтималдықтарды есептейтін модель де емес. <b>Decision Tree</b> ұқсас тармақ құрылымын қолданады, бірақ шарттарды оқыту деректерінен таңдап, жаңа мысал үшін болжам жасайды.</p></div>`;
 document.querySelector('.lesson-head').after(section);
 const $=s=>section.querySelector(s);let choices=[];
 const labels=['Бүгінгі сәт','Порталға кіру','Үйде қалу','Зерттеушілер әлемі','Жалғыз саяхатшы','Жаңа одақ','Тыныш өмір'];
 const outcomes=['Сен порталдан өтіп, серігіңмен жаңа әлемді зерттейсің.','Сен порталдан өтіп, белгісіз әлемді жалғыз зерттейсің.','Сен өз әлеміңде қалдың. Жаңа досыңмен ортақ жоба бастадың.','Сен өз әлеміңде қалып, таныс өміріңді жалғастырдың.'];
 function render(){
  const active=[0];if(choices.length)active.push(choices[0]?1:2);if(choices.length===2)active.push(3+(choices[0]?0:2)+(choices[1]?0:1));
  const points=[[500,46],[265,160],[735,160],[135,292],[375,292],[625,292],[865,292]];
  let svg='<svg viewBox="0 0 1000 370" role="img" aria-label="Бір бастау, екі таңдау және төрт мүмкін нәтиже бар оқиғалар ағашы">';
  for(let i=1;i<points.length;i++){const p=i<3?0:Math.floor((i-1)/2),[x,y]=points[p],[xx,yy]=points[i];svg+=`<path d="M${x} ${y+23}C${x} ${y+80},${xx} ${yy-75},${xx} ${yy-23}" fill="none" stroke="${active.includes(i)?'var(--accent)':'var(--line)'}" stroke-width="${active.includes(i)?3:1.5}"/><text x="${(x+xx)/2}" y="${(y+yy)/2+3}" text-anchor="middle" fill="var(--muted)" font-size="11">${i%2?'Иә':'Жоқ'}</text>`}
  points.forEach(([x,y],i)=>{const on=active.includes(i);svg+=`<g role="button" tabindex="0" data-universe="${i}" aria-label="${labels[i]}${on?', таңдалған жол':''}"><rect x="${x-94}" y="${y-23}" width="188" height="46" rx="23" fill="${on?'var(--accent)':'var(--panel)'}" stroke="${on?'var(--accent)':'var(--line)'}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="13" fill="${on?'var(--bg)':'var(--ink)'}">${labels[i]}</text>${i>2?`<text x="${x}" y="${y+49}" text-anchor="middle" fill="var(--muted)" font-size="10">ӘЛЕМ 0${i-2}</text>`:''}</g>`});
  $('#universe-tree').innerHTML=svg+'</svg>';
  $('#universe-count').textContent=`${choices.length} / 2 ТАҢДАУ`;
  const done=choices.length===2;
  $('#universe-question').textContent=done?labels[active.at(-1)]:choices.length?'Бейтаныс адамға сенесің бе?':'Порталға кіресің бе?';
  $('#universe-result').textContent=done?outcomes[active.at(-1)-3]:'Таңдауыңды жаса немесе ағаштағы кез келген нәтижені бас.';
  $('#universe-yes').textContent=choices.length?'Иә, сенемін':'Иә, кіремін';$('#universe-no').textContent=choices.length?'Жоқ, сенбеймін':'Жоқ, қаламын';
  $('#universe-yes').hidden=done;$('#universe-no').hidden=done;
  section.querySelectorAll('[data-universe]').forEach(n=>{const choose=()=>{const i=+n.dataset.universe;choices=i===0?[]:i<3?[i===1]:[i<5,i%2===1];render()};n.onclick=choose;n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}});
 }
 $('#universe-yes').onclick=()=>{choices.push(true);render()};$('#universe-no').onclick=()=>{choices.push(false);render()};$('#universe-reset').onclick=()=>{choices=[];render()};render();
}
